package com.masaakis.integration;
import org.flywaydb.core.Flyway;import org.junit.jupiter.api.Test;import org.testcontainers.junit.jupiter.*;import org.testcontainers.postgresql.PostgreSQLContainer;import static org.assertj.core.api.Assertions.*;
@Testcontainers(disabledWithoutDocker=true)class MigrationContainerTest{@Container static PostgreSQLContainer postgres=new PostgreSQLContainer("postgres:17-alpine");@Test void allMigrationsApplyWithRls(){var flyway=Flyway.configure().dataSource(postgres.getJdbcUrl(),postgres.getUsername(),postgres.getPassword()).locations("classpath:db/migration").load();var result=flyway.migrate();assertThat(result.success).isTrue();assertThat(flyway.info().current().getVersion().getVersion()).isEqualTo("11");try(var c=postgres.createConnection("");var s=c.createStatement();var rs=s.executeQuery("select count(*) from pg_class where relkind='r' and relrowsecurity")){assertThat(rs.next()).isTrue();assertThat(rs.getInt(1)).isGreaterThan(20);}catch(Exception e){throw new AssertionError(e);}}}
